const toggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('#navigation');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','메뉴 열기');nav.classList.remove('open')}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','메뉴 열기');toggle.focus()}});
const steps=[{image:'multilingual-table',alt:'서로 다른 언어를 쓰는 손님들이 편하게 식사하는 모습',rami:'hello',title:'반가워요! 어떤 언어가 편하세요?',subtitle:'라미가 손님의 언어로 안내해요.',content:'<span>한국어</span><span class="selected">Tiếng Việt <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></span><span>English</span><span>日本語</span>'},{image:'table-qr',alt:'테이블의 QR로 샵과 대화를 시작하는 손님',rami:'ordering',title:'많이 맵지 않은 메뉴를 추천해줘요.',subtitle:'재료를 물어보고, 원하는 메뉴를 골라요.',content:'<span class="dialogue"><b>손님의 베트남어 요청</b>Cho tôi một phần, ít cay nhé.</span><span class="dialogue"><b>사장님에게는 한국어로</b>1인분 주문할게요. 덜 맵게 부탁해요.</span>'},{image:'service-desk',alt:'사장님과 홀, 주방이 함께 주문을 확인하는 샵',rami:'cooking',title:'3번 테이블 주문, 준비가 끝났어요.',subtitle:'같은 주문을 보고, 다음 할 일을 알아요.',content:'<span class="order-state"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg> 홀 접수</span><span class="order-state"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg> 주방 준비 완료</span><span class="dialogue"><b>손님에게는 베트남어로</b>Món ăn của bạn đã sẵn sàng!</span>'}];
const tabs=[...document.querySelectorAll('[role=tab]')];
function selectStep(index,focus=false){tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1});const step=steps[index];const image=document.querySelector('#journey-image');image.src=`../../assets/one-shop/stories/${step.image}.webp`;image.alt=step.alt;document.querySelector('#panel-rami').src=`../../assets/one-shop/rami/expressions/${step.rami}.webp`;document.querySelector('#panel-title').textContent=step.title;document.querySelector('#panel-subtitle').textContent=step.subtitle;document.querySelector('#panel-content').innerHTML=step.content;document.querySelector('#journey-panel').setAttribute('aria-labelledby',`step-${index}`);if(focus)tabs[index].focus()}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectStep(i));tab.addEventListener('keydown',e=>{let index=i;if(e.key==='ArrowDown'||e.key==='ArrowRight')index=(i+1)%tabs.length;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')index=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();selectStep(index,true)})});
